function x({registerIndicator:w,sourceValues:s,nulls:y}){w({id:"oa-kendall",name:"Kendall Rank Correlation (KENDALL)",category:"Statistics",placement:"pane",inputs:[{key:"source1",type:"source",label:"Source 1",default:"close"},{key:"source2",type:"source",label:"Source 2",default:"volume",tooltip:"The Pine source reads a second ticker here, which a chart study cannot fetch. Both series are the current instrument."},{key:"period",type:"number",label:"Period",default:20,min:2,max:60,step:1,tooltip:"Bars in the window. The source function documents a maximum of 60; every pair in the window is compared, so the work grows with its square."}],plots:[{key:"tau",type:"line",title:"Kendall's Tau",style:{color:"#ffeb3b",lineWidth:2,precision:4}}],calc(a,i){const t=Math.min(60,Math.max(2,Math.floor(Number(i.period)||20))),b=s(a,i.source1??"close"),k=s(a,i.source2??"volume"),u=a.length,d=new Array(u).fill(NaN),c=new Array(t),l=new Array(t),N=t*(t-1)/2;for(let r=t-1;r<u;r++){const f=r-t+1;let m=!1;for(let e=0;e<t;e++){const o=b[f+e],n=k[f+e];if(!Number.isFinite(o)||!Number.isFinite(n)){m=!0;break}c[e]=o,l[e]=n}if(m)continue;let p=0,h=0;for(let e=0;e<t-1;e++)for(let o=e+1;o<t;o++){const n=(c[e]-c[o])*(l[e]-l[o]);n>0?p+=1:n<0&&(h+=1)}d[r]=(p-h)/N}return{tau:y(d)}}})}export{x as default};
